-- V3: Create seasons, season_teams and games tables.
-- Double round-robin fixture is generated by FixtureGenerator (ADR-0008).
-- Aggregate boundaries reference by id rather than entity objects (ADR-0003).
-- Scores and quarter details are omitted; they will arrive with result entry in a future slice (ADR-0003).
-- ON DELETE CASCADE: deleting a season removes its team memberships and games.
-- ON DELETE RESTRICT: teams participating in a season or game cannot be deleted by mistake.

SET lock_timeout = '15s';

CREATE TABLE seasons (
    id          bigint GENERATED ALWAYS AS IDENTITY,
    name        varchar(100) NOT NULL,
    start_date  date         NOT NULL,
    status      varchar(10)  NOT NULL,

    CONSTRAINT pk_seasons PRIMARY KEY (id),
    CONSTRAINT uq_seasons_name UNIQUE (name),
    CONSTRAINT ck_seasons_status CHECK (status IN ('DRAFT', 'ACTIVE', 'FINISHED'))
);

CREATE TABLE season_teams (
    season_id  bigint NOT NULL,
    team_id    bigint NOT NULL,

    CONSTRAINT pk_season_teams PRIMARY KEY (season_id, team_id),
    CONSTRAINT fk_season_teams_season FOREIGN KEY (season_id) REFERENCES seasons (id) ON DELETE CASCADE,
    CONSTRAINT fk_season_teams_team FOREIGN KEY (team_id) REFERENCES teams (id) ON DELETE RESTRICT
);

CREATE INDEX idx_season_teams_team_id ON season_teams (team_id);

CREATE TABLE games (
    id            bigint GENERATED ALWAYS AS IDENTITY,
    season_id     bigint       NOT NULL,
    round_no      integer      NOT NULL,
    home_team_id  bigint       NOT NULL,
    away_team_id  bigint       NOT NULL,
    status        varchar(10)  NOT NULL,
    version       bigint       NOT NULL DEFAULT 0,

    CONSTRAINT pk_games PRIMARY KEY (id),
    CONSTRAINT fk_games_season FOREIGN KEY (season_id) REFERENCES seasons (id) ON DELETE CASCADE,
    CONSTRAINT fk_games_home_team FOREIGN KEY (home_team_id) REFERENCES teams (id) ON DELETE RESTRICT,
    CONSTRAINT fk_games_away_team FOREIGN KEY (away_team_id) REFERENCES teams (id) ON DELETE RESTRICT,
    CONSTRAINT ck_games_round_no CHECK (round_no >= 1),
    CONSTRAINT ck_games_teams_different CHECK (home_team_id <> away_team_id),
    CONSTRAINT ck_games_status CHECK (status IN ('SCHEDULED', 'LIVE', 'FINISHED', 'CONFIRMED')),
    CONSTRAINT uq_games_season_round_home UNIQUE (season_id, round_no, home_team_id),
    CONSTRAINT uq_games_season_round_away UNIQUE (season_id, round_no, away_team_id)
);

CREATE INDEX idx_games_season_id ON games (season_id);
CREATE INDEX idx_games_home_team_id ON games (home_team_id);
CREATE INDEX idx_games_away_team_id ON games (away_team_id);
